import{_ as e,o as i,c as o,ag as a}from"./chunks/framework.BwSLX4ak.js";const b=JSON.parse('{"title":"生产环境安全清单","description":"","frontmatter":{},"headers":[],"relativePath":"shitbot/security.md","filePath":"shitbot/security.md"}'),d={name:"shitbot/security.md"};function t(c,l,r,s,n,u){return i(),o("div",null,[...l[0]||(l[0]=[a('<h1 id="生产环境安全清单" tabindex="-1">生产环境安全清单 <a class="header-anchor" href="#生产环境安全清单" aria-label="Permalink to &quot;生产环境安全清单&quot;">​</a></h1><h2 id="onebot" tabindex="-1">OneBot <a class="header-anchor" href="#onebot" aria-label="Permalink to &quot;OneBot&quot;">​</a></h2><ul><li>生产环境设置非空且不可猜测的 Access Token；</li><li>限制 <code>allowed-group-ids</code>，避免使用 <code>allow-all-groups: true</code>；</li><li>同机使用 <code>ws://127.0.0.1</code>；</li><li>跨主机使用 <code>wss://</code>；</li><li>只有在可信加密隧道中才考虑 <code>allow-insecure-remote-websocket</code>；</li><li>通过防火墙限制 OneBot 端口来源；</li><li>不要在日志、截图或 Issue 中公开 Token。</li></ul><h2 id="数据库" tabindex="-1">数据库 <a class="header-anchor" href="#数据库" aria-label="Permalink to &quot;数据库&quot;">​</a></h2><ul><li>为 ShitBot 创建独立数据库账号；</li><li>只授予目标数据库所需权限；</li><li>远程 MySQL 使用 <code>sslMode=VERIFY_IDENTITY</code>；</li><li>保持 <code>allowPublicKeyRetrieval=false</code>；</li><li>不要在多个进程间共享 SQLite 文件；</li><li>升级、迁移和更换平台前备份；</li><li>不要公开数据库 URL、账号或密码。</li></ul><h2 id="代理—后端通道" tabindex="-1">代理—后端通道 <a class="header-anchor" href="#代理—后端通道" aria-label="Permalink to &quot;代理—后端通道&quot;">​</a></h2><ul><li>每个后端使用不同的至少 16 位随机 Token；</li><li>同机 listener 绑定 <code>127.0.0.1</code>；</li><li>跨机器启用 TLS；</li><li>后端 <code>allowed-proxy-addresses</code> 只填写代理实际 IP；</li><li>防火墙只允许代理访问监听端口；</li><li>不要把 listener 直接暴露到公网；</li><li>TLS 环境仍保留 HMAC Token；</li><li>需要更强身份校验时启用双向 TLS。</li></ul><p>HMAC 提供请求认证和完整性，不提供内容加密。跨机器通信必须由 TLS 或可信加密隧道保护。</p><h2 id="qq-快捷命令" tabindex="-1">QQ 快捷命令 <a class="header-anchor" href="#qq-快捷命令" aria-label="Permalink to &quot;QQ 快捷命令&quot;">​</a></h2><ul><li>只配置确实需要的控制台命令；</li><li>为敏感快捷命令填写 <code>permission</code>；</li><li>保持 <code>allow-unbound: false</code>；</li><li>限制允许群和命令别名；</li><li>不要把任意群输入直接拼接进开放式控制台命令；</li><li>定期检查 LuckPerms、Vault 和 OP 权限；</li><li>观察命令冷却、超时和队列是否符合实际负载。</li></ul><p><code>permission</code> 为空只表示不检查游戏权限。将 <code>allow-unbound</code> 设为 <code>true</code> 才会允许未绑定群成员调用，因此修改此项前必须重新评估命令风险。</p><h2 id="高级图片模板" tabindex="-1">高级图片模板 <a class="header-anchor" href="#高级图片模板" aria-label="Permalink to &quot;高级图片模板&quot;">​</a></h2><ul><li>不需要高级模板时保持 <code>custom-image-templates.enabled: false</code>，此时不会下载或加载渲染组件；</li><li>只使用官方 Release 中同版本的 <code>ShitBotRenderer</code>、<code>.sha256</code> 和 <code>.sig</code>，不要绕过组件签名；</li><li>编辑器保持回环监听，通过 HTTPS 反向代理远程使用时不要直接公开内部端口，并保留原始 <code>Host</code>；</li><li><code>/shitbot editor</code> 登录地址是短时一次性凭据，不要发送到群聊、日志或 Issue；</li><li>保持远程图片关闭；确需开启时，仍应限制来源和资源上限；</li><li>不要手工修改 <code>versions/</code> 与 <code>published.yml</code>，生产渲染只应使用发布快照；</li><li>不要无上限提高画布、像素、图层、循环、资源、超时、线程和队列限制；</li><li>自定义数据提供器必须在访问平台 API 时自行切换到正确线程，并只返回渲染所需数据。</li></ul><p>当前模板引擎不执行上传的 HTML、JavaScript 或任意服务器命令，也不包含浏览器内核。<code>commands.yml</code> 的图片模板入口与控制台快捷命令是两套独立机制。</p><h2 id="账号绑定" tabindex="-1">账号绑定 <a class="header-anchor" href="#账号绑定" aria-label="Permalink to &quot;账号绑定&quot;">​</a></h2><ul><li>保持验证码有效期和尝试次数限制；</li><li>不要把 <code>code-alphabet</code> 改成过小字符集；</li><li>按服务器业务设置 <code>maximum-ids-per-qq</code>；</li><li>开启 <code>group-leave-unbind</code> 前确认退群即解绑符合业务规则；</li><li>数据库异常时不要绕过绑定检查；</li><li>处理迁移文件后及时移走 EasyBot 数据库副本。</li></ul><h2 id="更新" tabindex="-1">更新 <a class="header-anchor" href="#更新" aria-label="Permalink to &quot;更新&quot;">​</a></h2><ul><li>只从官方 GitHub Release 获取 JAR；</li><li>保留 <code>.sha256</code> 与 <code>.sig</code> 校验链；</li><li>更新失败时检查原因，不绕过签名；</li><li>群组服同时更新代理和后端；</li><li>替换 JAR 后正常重启，不使用插件管理器热加载；</li><li>发布私钥只保存在仓库 Secret。</li></ul><h2 id="日志与备份" tabindex="-1">日志与备份 <a class="header-anchor" href="#日志与备份" aria-label="Permalink to &quot;日志与备份&quot;">​</a></h2><ul><li>对外发送日志前删除 Token、密码、数据库地址和玩家隐私；</li><li>QQ 快捷命令的日志脱敏只是额外保护，不应替代最小权限；</li><li>数据库备份应加密并限制访问；</li><li>配置备份中同样包含敏感信息；</li><li>不要把生产配置、数据库或签名私钥提交到 Git；</li><li>定期确认备份可以恢复。</li></ul><h2 id="网络与资源" tabindex="-1">网络与资源 <a class="header-anchor" href="#网络与资源" aria-label="Permalink to &quot;网络与资源&quot;">​</a></h2><ul><li>限制数据库、OneBot、后端 listener 和管理面板端口的来源；</li><li>为远程服务配置连接与读取超时；</li><li>不要无上限提高数据库、图片渲染、数据提供器或命令队列；</li><li>背包资源包和客户端 JAR 只使用可信来源；</li><li>头像与外部图片服务应使用 HTTPS。</li></ul>',22)])])}const m=e(d,[["render",t]]);export{b as __pageData,m as default};
